CREATE TABLE `NewsletterVerificationToken` (`id` CHAR(36) NOT NULL, `subscriptionId` CHAR(36) NOT NULL, `tokenHash` CHAR(64) NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `usedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `NewsletterVerificationToken_tokenHash_key` (`tokenHash`), KEY `NewsletterVerificationToken_subscriptionId_usedAt_expiresAt_idx` (`subscriptionId`,`usedAt`,`expiresAt`), CONSTRAINT `NewsletterVerificationToken_subscriptionId_fkey` FOREIGN KEY (`subscriptionId`) REFERENCES `NewsletterSubscription` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
